(async()=>{const root='Infinite-Challenge-Concert-20260919/',prefix='https://api.github.com/repos/rainyyangg/rainyyangg-Jessica/git/trees/main?recursive=1';const summary=document.getElementById('summary'),phases=document.getElementById('phases'),photographers=document.getElementById('photographers'),grid=document.getElementById('grid'),heading=document.getElementById('phase-heading'),overlay=document.getElementById('overlay');const data={'演唱會':new Map(),'彩排':new Map()};try{const res=await fetch(prefix,{headers:{Accept:'application/vnd.github+json'}});if(!res.ok)throw Error('GitHub API '+res.status);const tree=await res.json();if(tree.truncated)throw Error('檔案清單過長，無法完整讀取');for(const file of tree.tree||[]){if(file.type!=='blob'||!file.path.startsWith(root)||!/\.(jpe?g|png|webp|gif|avif)$/i.test(file.path))continue;const parts=file.path.slice(root.length).split('/');let phase,person,name;if(parts[0]==='彩排'&&parts.length===3){phase='彩排';person=parts[1];name=parts[2]}else if(parts.length===2){phase='演唱會';person=parts[0];name=parts[1]}else continue;const group=data[phase];if(!group.has(person))group.set(person,[]);group.get(person).push({name,src:root.split('/').filter(Boolean).concat(parts).map(encodeURIComponent).join('/'),person})}let phase='演唱會',person='',visible=[],currentIndex=0;function showAt(i){if(!visible.length)return;currentIndex=(i+visible.length)%visible.length;const item=visible[currentIndex];overlay.querySelector('img').src=item.src;overlay.querySelector('p').textContent=item.person+' · '+item.name+' ('+(currentIndex+1)+'/'+visible.length+')';overlay.classList.add('open')}const total=Object.values(data).reduce((n,m)=>n+[...m.values()].reduce((v,a)=>v+a.length,0),0);summary.textContent=total+' 張可瀏覽照片 · 演唱會 / 彩排 · 依攝影者分類';function render(){phases.replaceChildren();for(const label of ['演唱會','彩排']){const b=document.createElement('button');b.textContent=label+' ('+[...data[label].values()].reduce((n,a)=>n+a.length,0)+')';b.className=phase===label?'active':'';b.onclick=()=>{phase=label;person='';render()};phases.append(b)}heading.textContent=phase;photographers.replaceChildren();const group=data[phase];if(!group.has(person))person=[...group.keys()].sort((a,b)=>a.localeCompare(b))[0];for(const name of [...group.keys()].sort((a,b)=>a.localeCompare(b))){const b=document.createElement('button');b.textContent=name+' ('+group.get(name).length+')';b.className=person===name?'active':'';b.onclick=()=>{person=name;render()};photographers.append(b)}grid.replaceChildren();visible=[...(group.get(person)||[])].sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true}));for(const [i,item] of visible.entries()){const b=document.createElement('button'),img=document.createElement('img'),cap=document.createElement('span');img.loading='lazy';img.src=item.src;img.alt=item.person+' '+item.name;cap.textContent=item.person+' · '+item.name;b.append(img,cap);b.onclick=()=>showAt(i);grid.append(b)}}render()}catch(err){summary.textContent='暫時無法載入照片清單，請稍後重試。('+err.message+')'}overlay.querySelector('button').onclick=()=>overlay.classList.remove('open');overlay.onclick=e=>{if(e.target===overlay)overlay.classList.remove('open')};document.addEventListener('keydown',e=>{if(e.key==='Escape')overlay.classList.remove('open');if(overlay.classList.contains('open')&&e.key==='ArrowRight'){e.preventDefault();showAt(currentIndex+1)}if(overlay.classList.contains('open')&&e.key==='ArrowLeft'){e.preventDefault();showAt(currentIndex-1)}})})();